// ruleid: metric/cyclomatic-complexity
function complex(v: number): number {
  let r = 0;
  if (v > 1) { r += 1; }
  if (v > 2) { r += 2; }
  if (v > 3) { r += 3; }
  if (v > 4) { r += 4; }
  if (v > 5) { r += 5; }
  if (v > 6) { r += 6; }
  if (v > 7) { r += 7; }
  if (v > 8) { r += 8; }
  if (v > 9) { r += 9; }
  if (v > 10) { r += 10; }
  if (v > 11) { r += 11; }
  if (v > 12) { r += 12; }
  if (v > 13) { r += 13; }
  if (v > 14) { r += 14; }
  if (v > 15) { r += 15; }
  if (v > 16) { r += 16; }
  if (v > 17) { r += 17; }
  if (v > 18) { r += 18; }
  if (v > 19) { r += 19; }
  if (v > 20) { r += 20; }
  if (v > 21) { r += 21; }
  if (v > 22) { r += 22; }
  if (v > 23) { r += 23; }
  if (v > 24) { r += 24; }
  if (v > 25) { r += 25; }
  if (v > 26) { r += 26; }
  return r;
}
